class Solution {
    struct Node {
        long long dp[2][2];
    };
    vector<Node> tree;
    void pull(int node) {
        int lc = 2 * node, rc = 2 * node + 1;
        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j < 2; ++j) {
                tree[node].dp[i][j] = max(
                    tree[lc].dp[i][0] + tree[rc].dp[1][j],
                    tree[lc].dp[i][1] + tree[rc].dp[0][j]
                );
            }
        }
    }
    void build(int node, int l, int r, const vector<int>& nums) {
        if (l == r) {
            tree[node].dp[0][0] = 0;
            tree[node].dp[0][1] = 0;
            tree[node].dp[1][0] = 0;
            tree[node].dp[1][1] = max(0, nums[l]);
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, nums);
        build(2 * node + 1, mid + 1, r, nums);
        pull(node);
    }
    void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            tree[node].dp[1][1] = max(0, val);
            return;
        }
        int mid = (l + r) / 2;
        if (idx <= mid) update(2 * node, l, mid, idx, val);
        else update(2 * node + 1, mid + 1, r, idx, val);
        pull(node);
    }
public:
    int maximumSumSubsequence(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        tree.resize(4 * n);
        build(1, 0, n - 1, nums);
        long long ans = 0;
        long long MOD = 1e9 + 7;
        for (const auto& q : queries) {
            update(1, 0, n - 1, q[0], q[1]);
            ans = (ans + tree[1].dp[1][1]) % MOD;
        }
        return ans;
    }
};

class Solution {
    static class Node {
        long[][] dp = new long[2][2];
    }
    private Node[] tree;
    private void pull(int node) {
        int lc = 2 * node, rc = 2 * node + 1;
        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j < 2; ++j) {
                tree[node].dp[i][j] = Math.max(
                    tree[lc].dp[i][0] + tree[rc].dp[1][j],
                    tree[lc].dp[i][1] + tree[rc].dp[0][j]
                );
            }
        }
    }
    private void build(int node, int l, int r, int[] nums) {
        tree[node] = new Node();
        if (l == r) {
            tree[node].dp[1][1] = Math.max(0, nums[l]);
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, nums);
        build(2 * node + 1, mid + 1, r, nums);
        pull(node);
    }
    private void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            tree[node].dp[1][1] = Math.max(0, val);
            return;
        }
        int mid = (l + r) / 2;
        if (idx <= mid) update(2 * node, l, mid, idx, val);
        else update(2 * node + 1, mid + 1, r, idx, val);
        pull(node);
    }
    public int maximumSumSubsequence(int[] nums, int[][] queries) {
        int n = nums.length;
        tree = new Node[4 * n];
        build(1, 0, n - 1, nums);
        long ans = 0;
        long MOD = 1_000_000_007L;
        for (int[] q : queries) {
            update(1, 0, n - 1, q[0], q[1]);
            ans = (ans + tree[1].dp[1][1]) % MOD;
        }
        return (int) ans;
    }
}

var maximumSumSubsequence = function(nums, queries) {
    const MOD = 1000000007n;
    const n = nums.length;
    const tree00 = new BigInt64Array(4 * n);
    const tree01 = new BigInt64Array(4 * n);
    const tree10 = new BigInt64Array(4 * n);
    const tree11 = new BigInt64Array(4 * n);

    function pull(node) {
        const lc = 2 * node, rc = 2 * node + 1;
        const a00 = tree00[lc] + tree10[rc], b00 = tree01[lc] + tree00[rc];
        tree00[node] = a00 > b00 ? a00 : b00;
        const a01 = tree00[lc] + tree11[rc], b01 = tree01[lc] + tree01[rc];
        tree01[node] = a01 > b01 ? a01 : b01;
        const a10 = tree10[lc] + tree10[rc], b10 = tree11[lc] + tree00[rc];
        tree10[node] = a10 > b10 ? a10 : b10;
        const a11 = tree10[lc] + tree11[rc], b11 = tree11[lc] + tree01[rc];
        tree11[node] = a11 > b11 ? a11 : b11;
    }
    function build(node, l, r) {
        if (l === r) {
            const v = BigInt(Math.max(0, nums[l]));
            tree11[node] = v;
            return;
        }
        const mid = (l + r) >> 1;
        build(2 * node, l, mid);
        build(2 * node + 1, mid + 1, r);
        pull(node);
    }
    function update(node, l, r, idx, val) {
        if (l === r) {
            tree11[node] = BigInt(Math.max(0, val));
            return;
        }
        const mid = (l + r) >> 1;
        if (idx <= mid) update(2 * node, l, mid, idx, val);
        else update(2 * node + 1, mid + 1, r, idx, val);
        pull(node);
    }
    build(1, 0, n - 1);
    let ans = 0n;
    for (const [pos, x] of queries) {
        update(1, 0, n - 1, pos, x);
        ans = (ans + tree11[1]) % MOD;
    }
    return Number(ans);
};
